import bannerImg from "../assets/image.png";
import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import Swal from "sweetalert2";

// ── Datos simulados ────────────────────────────────────────────────
const DETECCIONES = [
  { id: 1, fecha: "24/07/2025", hora: "09:15 a.m.", lote: "Lote 7", bloque: "Bloque E", resultado: "Sigatoka Negra", severidad: "Moderado", image: "https://images.unsplash.com/photo-1524593166156-312f362cada0?q=80&w=100" },
  { id: 2, fecha: "24/07/2025", hora: "08:45 a.m.", lote: "Lote 6", bloque: "Bloque A", resultado: "Sigatoka Negra", severidad: "Severo",   image: "https://images.unsplash.com/photo-1501004318641-b39e6451bec6?q=80&w=100" },
  { id: 3, fecha: "24/07/2025", hora: "04:30 p.m.", lote: "Lote 5", bloque: "Bloque D", resultado: "Sigatoka Negra", severidad: "Leve",     image: "https://images.unsplash.com/photo-1471193945509-9ad0617afabf?q=80&w=100" },
  { id: 4, fecha: "23/07/2025", hora: "11:20 a.m.", lote: "Lote 4", bloque: "Bloque B", resultado: "Sigatoka Negra", severidad: "Moderado", image: "https://images.unsplash.com/photo-1466692476868-aef1dfb1e735?q=80&w=100" },
  { id: 5, fecha: "22/07/2025", hora: "03:10 p.m.", lote: "Lote 3", bloque: "Bloque C", resultado: "Sana",           severidad: "Leve",     image: "https://images.unsplash.com/photo-1524593166156-312f362cada0?q=80&w=100" },
];

const LOTES = [
  { nombre: "Lote 7 - Bloque B", cantidad: 28 },
  { nombre: "Lote 6 - Bloque A", cantidad: 24 },
  { nombre: "Lote 5 - Bloque D", cantidad: 20 },
  { nombre: "Lote 4 - Bloque B", cantidad: 18 },
  { nombre: "Lote 3 - Bloque C", cantidad: 16 },
];

const EVOLUCION = [
  { dia: "18 Jul", val: 22 },
  { dia: "19 Jul", val: 38 },
  { dia: "20 Jul", val: 45 },
  { dia: "21 Jul", val: 30 },
  { dia: "22 Jul", val: 52 },
  { dia: "23 Jul", val: 48 },
  { dia: "24 Jul", val: 68 },
];

const severidadConfig = {
  Moderado: { bg: "bg-amber-100", text: "text-amber-700", border: "border-amber-200" },
  Severo:   { bg: "bg-red-100",   text: "text-red-600",  border: "border-red-200"   },
  Leve:     { bg: "bg-emerald-100", text: "text-emerald-700", border: "border-emerald-200" },
};

const resultadoColor = {
  "Sigatoka Negra": "text-red-500",
  "Sana":           "text-emerald-600",
};

// ── Componente principal ───────────────────────────────────────────
export default function HomePage() {
  const navigate   = useNavigate();
  const { user, handleLogout } = useAuth();
  const [activePage, setActivePage] = useState("dashboard");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [detections, setDetections] = useState([]);
  const canvasRef = useRef(null);

  const firstName = user?.displayName
    ? user.displayName.split(" ")[0]
    : user?.email ? user.email.split("@")[0] : "Usuario";

  const fullName = user?.displayName || user?.email?.split("@")[0] || "Usuario";

  const initials = fullName.split(" ").map(n => n[0]).join("").toUpperCase().slice(0, 2);

  const storageKey = `scans_${user?.uid || user?.email || "guest"}`;

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem(storageKey) || "[]");
    setDetections(saved);
  }, [user]);

  useEffect(() => {
    dibujarGrafica();
  }, []);

  const dibujarGrafica = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const W = canvas.width, H = canvas.height;
    const pad = { top: 20, right: 20, bottom: 30, left: 40 };
    const vals = EVOLUCION.map(e => e.val);
    const maxVal = Math.max(...vals);
    const minVal = 0;

    ctx.clearRect(0, 0, W, H);

    // Grid lines - más suaves
    for (let i = 0; i <= 4; i++) {
      const y = pad.top + ((H - pad.top - pad.bottom) / 4) * i;
      ctx.strokeStyle = "#f0f0f0";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(pad.left, y);
      ctx.lineTo(W - pad.right, y);
      ctx.stroke();
      const label = Math.round(maxVal - (maxVal / 4) * i);
      ctx.fillStyle = "#9ca3af";
      ctx.font = "10px Inter, sans-serif";
      ctx.textAlign = "right";
      ctx.fillText(label, pad.left - 6, y + 4);
    }

    const pts = EVOLUCION.map((e, i) => ({
      x: pad.left + (i / (EVOLUCION.length - 1)) * (W - pad.left - pad.right),
      y: pad.top + (1 - (e.val - minVal) / (maxVal - minVal)) * (H - pad.top - pad.bottom),
    }));

    // Área bajo la curva - más suave
    const grad = ctx.createLinearGradient(0, pad.top, 0, H - pad.bottom);
    grad.addColorStop(0, "rgba(22, 78, 33, 0.15)");
    grad.addColorStop(1, "rgba(22, 78, 33, 0)");
    ctx.beginPath();
    ctx.moveTo(pts[0].x, H - pad.bottom);
    pts.forEach(p => ctx.lineTo(p.x, p.y));
    ctx.lineTo(pts[pts.length - 1].x, H - pad.bottom);
    ctx.closePath();
    ctx.fillStyle = grad;
    ctx.fill();

    // Línea principal
    ctx.beginPath();
    ctx.strokeStyle = "#1a5e1a";
    ctx.lineWidth = 2.5;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    pts.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
    ctx.stroke();

    // Puntos con efecto
    pts.forEach(p => {
      // Sombra
      ctx.beginPath();
      ctx.arc(p.x, p.y, 6, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(26, 94, 26, 0.2)";
      ctx.fill();
      
      // Punto principal
      ctx.beginPath();
      ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
      ctx.fillStyle = "#1a5e1a";
      ctx.fill();
      ctx.strokeStyle = "white";
      ctx.lineWidth = 2;
      ctx.stroke();
    });

    // Labels días
    EVOLUCION.forEach((e, i) => {
      const x = pad.left + (i / (EVOLUCION.length - 1)) * (W - pad.left - pad.right);
      ctx.fillStyle = "#6b7280";
      ctx.font = "10px Inter, sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(e.dia, x, H - 4);
    });
  };

  const confirmLogout = () => {
    Swal.fire({
      title: "¿Cerrar sesión?",
      text: "Tendrás que iniciar sesión de nuevo.",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#1f5e1f",
      cancelButtonColor: "#9ca3af",
      confirmButtonText: "Sí, cerrar sesión",
      cancelButtonText: "Cancelar",
      background: "#f5f2ec",
      customClass: { popup: "rounded-3xl" },
    }).then(result => {
      if (result.isConfirmed) {
        handleLogout();
        navigate("/login");
      }
    });
  };

  const navItems = [
    { key: "dashboard",  label: "Dashboard",                  icon: "📊" },
    { key: "usuarios",   label: "Usuarios",                   icon: "👥" },
    { key: "deteccion",  label: "Detección de Enfermedades",  icon: "🔬" },
    { key: "seguimiento",label: "Recomendación y Seguimiento",icon: "🌿" },
    { key: "geolocal",   label: "Geolocalización y Registro",icon: "📍" },
    { key: "informes",   label: "Visualización e Informes",   icon: "📈" },
  ];

  const handleNav = (key) => {
    setActivePage(key);
    setSidebarOpen(false);
    if (key === "geolocal") navigate("/map");
  };

  const totalScans     = detections.length || 128;
  const sigatokaNegra  = detections.filter(d => d.enfermedad === "Sigatoka Negra").length || 68;
  const moderadoSevero = detections.filter(d => ["Alto", "Medio"].includes(d.nivel_riesgo)).length || 42;
  const estaSemana     = 24;

  return (
    <div className="min-h-screen bg-[#f5f2ec] flex flex-col">

      {/* ── TOPBAR ── */}
      <header className="bg-white border-b border-[#e8e4de] px-6 py-4 flex items-center justify-between sticky top-0 z-30 shadow-sm">
        <div className="flex items-center gap-3">
          <button
            onClick={() => setSidebarOpen(true)}
            className="lg:hidden w-9 h-9 rounded-lg flex items-center justify-center hover:bg-gray-100"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>
          <div>
            <h1 className="text-xl font-bold text-[#1a2e1a] leading-tight">
              Panel de Control - Dashboard
            </h1>
            <p className="text-xs text-[#6b7280] font-medium">
              Resumen general de las operaciones de Sigatoka Negra
            </p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button className="relative w-10 h-10 rounded-full bg-[#f5f2ec] border border-[#e8e4de] flex items-center justify-center hover:bg-[#e8e4de] transition">
            <svg className="w-5 h-5 text-[#4a5a4a]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" />
            </svg>
            <span className="absolute -top-0.5 -right-0.5 w-5 h-5 bg-[#1a5e1a] text-white text-[10px] font-bold rounded-full flex items-center justify-center">3</span>
          </button>

          <div className="flex items-center gap-2.5 cursor-pointer">
            {user?.photoURL ? (
              <img src={user.photoURL} referrerPolicy="no-referrer" alt="avatar" className="w-9 h-9 rounded-full object-cover border-2 border-[#1a5e1a]" />
            ) : (
              <div className="w-9 h-9 rounded-full bg-[#1a5e1a] flex items-center justify-center text-white text-sm font-bold">
                {initials}
              </div>
            )}
            <div className="hidden sm:block">
              <p className="text-sm font-semibold text-[#1a2e1a] leading-tight">{fullName}</p>
              <p className="text-xs text-[#6b7280]">Técnico de Campo</p>
            </div>
            <svg className="w-4 h-4 text-[#6b7280]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </div>
        </div>
      </header>

      <div className="flex flex-1">

        {/* Overlay móvil */}
        {sidebarOpen && (
          <div className="fixed inset-0 bg-black/40 z-30 lg:hidden" onClick={() => setSidebarOpen(false)} />
        )}

        {/* ── SIDEBAR ── */}
        <aside className={`fixed lg:sticky top-0 left-0 h-screen lg:h-[calc(100vh-73px)] w-60 bg-[#1a2e1a] flex flex-col z-40 transition-transform duration-300
          ${sidebarOpen ? "translate-x-0" : "-translate-x-full"} lg:translate-x-0`}
        >
          {/* Logo */}
          <div className="flex items-center gap-3 px-5 py-5 border-b border-white/10">
            <div className="w-10 h-10 rounded-xl bg-[#1a5e1a] flex items-center justify-center shrink-0">
              <svg width="22" height="22" viewBox="0 0 80 80" fill="none">
                <ellipse cx="30" cy="40" rx="13" ry="20" fill="white" opacity="0.9" transform="rotate(-15 30 40)" />
                <ellipse cx="50" cy="38" rx="13" ry="20" fill="white" opacity="0.75" transform="rotate(15 50 38)" />
                <line x1="40" y1="60" x2="40" y2="72" stroke="white" strokeWidth="3" strokeLinecap="round" />
              </svg>
            </div>
            <div>
              <p className="text-white font-bold text-sm leading-tight">Sigatoka Negra</p>
              <p className="text-[#8ba88b] text-xs">Hacienda San Luis</p>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden ml-auto text-white/50 hover:text-white">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* Nav */}
          <nav className="flex-1 px-3 py-4 space-y-1 overflow-y-auto">
            {navItems.map(item => (
              <button
                key={item.key}
                onClick={() => handleNav(item.key)}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm transition text-left
                  ${activePage === item.key
                    ? "bg-[#1a5e1a] text-white font-semibold"
                    : "text-[#8ba88b] hover:bg-white/10 hover:text-white"
                  }`}
              >
                <span className="text-base shrink-0">{item.icon}</span>
                <span className="leading-snug">{item.label}</span>
              </button>
            ))}
          </nav>

          {/* Usuario + cerrar sesión */}
          <div className="px-3 pb-4 space-y-2 border-t border-white/10 pt-3">
            <div className="flex items-center gap-3 px-3 py-2.5 rounded-xl bg-white/10">
              {user?.photoURL ? (
                <img src={user.photoURL} referrerPolicy="no-referrer" alt="" className="w-8 h-8 rounded-full object-cover shrink-0" />
              ) : (
                <div className="w-8 h-8 rounded-full bg-[#1a5e1a] flex items-center justify-center text-white text-xs font-bold shrink-0">
                  {initials}
                </div>
              )}
              <div className="min-w-0">
                <p className="text-white text-xs font-semibold truncate">{fullName}</p>
                <p className="text-[#8ba88b] text-[11px] truncate">Técnico de Campo</p>
              </div>
              <svg className="w-4 h-4 text-white/40 ml-auto shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
              </svg>
            </div>
            <button
              onClick={confirmLogout}
              className="w-full flex items-center gap-2 px-3 py-2.5 rounded-xl text-[#8ba88b] hover:bg-white/10 hover:text-white transition text-sm"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
              </svg>
              Cerrar sesión
            </button>
          </div>
        </aside>

        {/* ── CONTENIDO PRINCIPAL ── */}
        <main className="flex-1 p-4 sm:p-6 space-y-5 overflow-auto">

          {/* STATS - 4 tarjetas */}
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
            {[
              { 
                icon: "🔍", 
                bg: "bg-[#f0f7f0]", 
                iconBg: "bg-[#1a5e1a]/10", 
                val: totalScans,     
                label: "Detecciones Totales",    
                sub: "↑ +15 esta semana",       
                subColor: "text-[#1a5e1a]" 
              },
              { 
                icon: "🍂", 
                bg: "bg-[#fef2f2]", 
                iconBg: "bg-red-100",    
                val: sigatokaNegra,  
                label: "Sigatoka Negra",         
                sub: "53.1% del total",       
                subColor: "text-red-500"   
              },
              { 
                icon: "⚠️", 
                bg: "bg-[#fffbeb]", 
                iconBg: "bg-amber-100", 
                val: moderadoSevero, 
                label: "Nivel Moderado - Severo", 
                sub: "32.8% del total",       
                subColor: "text-amber-600"
              },
              { 
                icon: "📅", 
                bg: "bg-[#eff6ff]", 
                iconBg: "bg-blue-100",   
                val: estaSemana,     
                label: "Detecciones esta semana", 
                sub: "+6 respecto a la semana pasada", 
                subColor: "text-blue-600"  
              },
            ].map((s, i) => (
              <div key={i} className={`${s.bg} rounded-2xl p-5 border border-white shadow-sm hover:shadow-md transition`}>
                <div className="flex items-start gap-3">
                  <div className={`${s.iconBg} w-12 h-12 rounded-2xl flex items-center justify-center text-2xl shrink-0`}>
                    {s.icon}
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="text-3xl font-bold text-[#1a2e1a]">{s.val}</p>
                    <p className="text-xs text-[#6b7280] font-medium leading-tight mt-0.5">{s.label}</p>
                    <p className={`text-xs font-semibold mt-1 ${s.subColor}`}>{s.sub}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* FILA MEDIA — tabla + donut */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">

            {/* Detecciones recientes */}
            <div className="lg:col-span-2 bg-white rounded-2xl border border-[#e8e4de] overflow-hidden shadow-sm">
              <div className="flex items-center justify-between px-6 py-4 border-b border-[#e8e4de]">
                <h2 className="font-bold text-[#1a2e1a]">Detecciones Recientes</h2>
                <button 
                  onClick={() => navigate("/scan")} 
                  className="text-[#1a5e1a] text-sm font-medium hover:underline"
                >
                  Ver todas →
                </button>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="bg-[#f5f2ec] text-[#6b7280] text-xs font-semibold">
                      <th className="text-left px-6 py-3">Fecha</th>
                      <th className="text-left px-4 py-3">Lote</th>
                      <th className="text-left px-4 py-3">Resultado</th>
                      <th className="text-left px-4 py-3">Severidad</th>
                      <th className="text-center px-4 py-3">Estado</th>
                    </tr>
                  </thead>
                  <tbody>
                    {DETECCIONES.map((d, i) => {
                      const sev = severidadConfig[d.severidad] || severidadConfig.Leve;
                      return (
                        <tr
                          key={d.id}
                          className={`border-t border-[#f0ede8] hover:bg-[#f5f2ec] transition cursor-pointer ${i % 2 === 0 ? 'bg-white' : 'bg-[#faf8f6]'}`}
                          onClick={() => navigate(`/result/${d.id}`)}
                        >
                          <td className="px-6 py-3">
                            <div className="flex items-center gap-3">
                              <img src={d.image} alt="" className="w-11 h-11 rounded-xl object-cover shrink-0" />
                              <div>
                                <p className="font-medium text-[#1a2e1a] text-sm">{d.fecha}</p>
                                <p className="text-[#6b7280] text-[11px]">{d.hora}</p>
                              </div>
                            </div>
                          </td>
                          <td className="px-4 py-3">
                            <p className="text-sm font-medium text-[#1a2e1a]">{d.lote}</p>
                            <p className="text-[11px] text-[#6b7280]">{d.bloque}</p>
                          </td>
                          <td className={`px-4 py-3 text-sm font-semibold ${resultadoColor[d.resultado] || "text-[#6b7280]"}`}>
                            {d.resultado}
                          </td>
                          <td className="px-4 py-3">
                            <span className={`text-xs font-semibold px-3 py-1.5 rounded-full border ${sev.bg} ${sev.text} ${sev.border}`}>
                              {d.severidad}
                            </span>
                          </td>
                          <td className="px-4 py-3 text-center">
                            <span className="text-[#1a5e1a] text-lg">👁️</span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Donut por severidad */}
            <div className="bg-white rounded-2xl border border-[#e8e4de] p-6 shadow-sm">
              <h2 className="font-bold text-[#1a2e1a] mb-4 text-center">Detecciones por Nivel de Sigatoka Negra</h2>
              <div className="flex flex-col items-center">
                <DonutChart />
                <div className="space-y-2.5 w-full mt-5">
                  {[
                    { label: "Leve",     val: 44, pct: "34.4%", color: "bg-emerald-500"  },
                    { label: "Moderado", val: 42, pct: "32.8%", color: "bg-amber-400" },
                    { label: "Severo",   val: 24, pct: "18.8%", color: "bg-red-500"    },
                    { label: "Sana",     val: 18, pct: "14.1%", color: "bg-[#1a5e1a]"  },
                  ].map((item, i) => (
                    <div key={i} className="flex items-center justify-between text-sm">
                      <div className="flex items-center gap-2.5">
                        <span className={`w-3.5 h-3.5 rounded-sm shrink-0 ${item.color}`} />
                        <span className="text-[#4a5a4a] font-medium">{item.label}</span>
                      </div>
                      <span className="text-[#1a2e1a] font-semibold">{item.val} ({item.pct})</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* FILA INFERIOR — gráfica + lotes + resumen */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">

            {/* Gráfica evolución */}
            <div className="bg-white rounded-2xl border border-[#e8e4de] p-6 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h2 className="font-bold text-[#1a2e1a]">Evolución de Casos de Sigatoka Negra</h2>
                <span className="text-xs text-[#6b7280] bg-[#f5f2ec] px-3 py-1.5 rounded-full font-medium">Últimos 7 días ▾</span>
              </div>
              <canvas ref={canvasRef} width={500} height={200} className="w-full" />
            </div>

            {/* Lotes + resumen */}
            <div className="flex flex-col gap-5">

              {/* Detecciones por lote */}
              <div className="bg-white rounded-2xl border border-[#e8e4de] p-6 shadow-sm">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="font-bold text-[#1a2e1a] text-sm">Lotes con Presencia de Sigatoka Negra</h2>
                  <button onClick={() => navigate("/map")} className="text-[#1a5e1a] text-xs font-medium hover:underline">
                    Ver mapa →
                  </button>
                </div>
                <div className="space-y-3">
                  {LOTES.map((lote, i) => {
                    const max = 28;
                    const pct = (lote.cantidad / max) * 100;
                    return (
                      <div key={i} className="flex items-center gap-3 text-sm">
                        <span className="text-[#4a5a4a] w-36 shrink-0 font-medium">{lote.nombre}</span>
                        <div className="flex-1 h-2.5 bg-[#f0ede8] rounded-full overflow-hidden">
                          <div
                            className="h-full bg-[#1a5e1a] rounded-full transition-all duration-500"
                            style={{ width: `${Math.min(pct, 100)}%` }}
                          />
                        </div>
                        <span className="text-[#1a2e1a] font-bold w-6 text-right shrink-0">{lote.cantidad}</span>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* Resumen diagnósticos */}
              <div className="bg-white rounded-2xl border border-[#e8e4de] p-6 shadow-sm">
                <h2 className="font-bold text-[#1a2e1a] text-sm mb-4 text-center">Resumen de Casos de Sigatoka Negra</h2>
                <div className="grid grid-cols-4 gap-3">
                  {[
                    { icon: "✅", val: 18,  label: "Sanas",          pct: "14.1%" },
                    { icon: "🍂", val: 68,  label: "Sigatoka Negra", pct: "53.1%" },
                    { icon: "⚠️", val: 42,  label: "Moderado - Severo",pct: "32.8%" },
                    { icon: "📊", val: 128, label: "Total",          pct: "" },
                  ].map((item, i) => (
                    <div key={i} className="text-center bg-[#faf8f6] rounded-xl p-3 border border-[#f0ede8]">
                      <div className="text-3xl mb-1.5">{item.icon}</div>
                      <p className={`font-bold text-xl ${i === 0 ? 'text-emerald-600' : i === 1 ? 'text-red-500' : i === 2 ? 'text-amber-600' : 'text-[#1a2e1a]'}`}>
                        {item.val}
                      </p>
                      <p className="text-[10px] text-[#6b7280] font-medium leading-tight">{item.label}</p>
                      {item.pct && <p className={`text-[10px] font-bold mt-0.5 ${i === 0 ? 'text-emerald-600' : i === 1 ? 'text-red-500' : i === 2 ? 'text-amber-600' : 'text-[#1a2e1a]'}`}>
                        {item.pct}
                      </p>}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Footer */}
          <div className="flex items-center justify-center gap-3 py-4 border-t border-[#e8e4de] mt-4">
            <span className="text-[#1a5e1a] text-lg">🛡️</span>
            <p className="text-xs text-[#6b7280] text-center font-medium">
              Sistema Inteligente para la detección y monitoreo de Sigatoka Negra en cultivos de banano - Versión 2.1
            </p>
          </div>

        </main>
      </div>
    </div>
  );
}

// ── Componente Donut separado ──
function DonutChart() {
  const ref = useRef(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const W = canvas.width, H = canvas.height;
    const cx = W / 2, cy = H / 2;
    const r  = Math.min(W, H) / 2 - 10;

    const datos = [
      { val: 44, color: "#10b981" }, // Leve - emerald
      { val: 42, color: "#f59e0b" }, // Moderado - amber
      { val: 24, color: "#ef4444" }, // Severo - red
      { val: 18, color: "#1a5e1a" }, // Sana - verde oscuro
    ];
    const total = datos.reduce((a, b) => a + b.val, 0);
    let startAngle = -Math.PI / 2;

    ctx.clearRect(0, 0, W, H);

    // Dibujar cada segmento
    datos.forEach(d => {
      const slice = (d.val / total) * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, r, startAngle, startAngle + slice);
      ctx.closePath();
      ctx.fillStyle = d.color;
      ctx.fill();
      startAngle += slice;
    });

    // Hueco central
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.5, 0, Math.PI * 2);
    ctx.fillStyle = "white";
    ctx.fill();

    // Sombra sutil en el hueco
    ctx.shadowColor = "rgba(0,0,0,0.05)";
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.5, 0, Math.PI * 2);
    ctx.fillStyle = "white";
    ctx.fill();
    ctx.shadowBlur = 0;

    // Texto central
    ctx.fillStyle = "#1a2e1a";
    ctx.font = "bold 20px Inter, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("128", cx, cy - 4);
    ctx.fillStyle = "#6b7280";
    ctx.font = "10px Inter, sans-serif";
    ctx.fillText("Total", cx, cy + 14);
  }, []);

  return <canvas ref={ref} width={160} height={160} className="w-40 h-40" />;
}
